#!/usr/bin/env node
// Regenerate the stylesheet bundle in the exact original HTML cascade order.
// No third-party packages: node scripts/build-css-bundle.mjs [--check]
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const sources = [
  "style.css",
  "task2.css",
  "task2-process-split-20261107.css",
  "action-layout-hotfix.css",
  "transport-application.css",
  "task2-contrast-hotfix.css",
  "transport-readability-20261107.css",
  "carrier-acceptance-workflow-20261107.css",
  "portal-feedback-center-20261107.css",
  "carrier-dashboard-compact-20261107.css",
  "lw2-staging-20261107.css",
  "carrier-defer-transport-application-20261107.css",
  "lw-premium-landing-20261108.css",
  "lw-approved-dark-20261108.css",
  "lw-public-cooperation-20261108.css",
  "current-workspace-help-20261108.css",
  "owner-workspace-compact-20261108.css",
  "owner-command-center-20261108.css",
  "owner-registers-20261111.css",
  "role-help-20261111.css",
  "portal-contrast-accessibility-20261108.css",
  "offer-edit-modal-readability-20261108.css",
  "global-view/leaflet.css",
  "global-view/view.css",
  "ved-single-workspace-20261108.css",
  "lw-pending-tasks-all-roles-20261109.css",
  "lw-ved-shared-chat-20261109.css",
  "lw-contrast-canonical-20261111.css",
  "task2-execution-layout-20261114.css",
  "public-support-20261115.css",
  "qa011-owner-winner-actions.css",
  "owner-ui-unification-20261117.css",
  "owner-team-users-20261117.css",
  "portal-release-status-20261117.css",
  "owner-audit-explanations-20261117.css",
  "offer-score-methodology-20261117.css",
  "lw-hover-safe-20261108.css"
];
const header = '/* Freight Quotes stylesheet bundle: keep original ordered cascade. Generated by scripts/build-css-bundle.mjs. */\n';

function rebase(css, filename) {
  if (!filename.includes('/')) return css;
  const prefix = filename.slice(0, filename.lastIndexOf('/') + 1);
  return css.replace(/url\(\s*(['"]?)([^'")]+)\1\s*\)/gi, (full, quote, url) => {
    if (/^(data:|https?:|\/\/|\/|#)/i.test(url)) return full;
    return 'url("' + prefix + url.replace(/^\.\//, '') + '")';
  });
}

const result = header + sources.map(file => {
  const css = readFileSync(resolve(root, file), 'utf8');
  return '/* --- SOURCE ' + file + ' --- */\n' + rebase(css, file) + '\n';
}).join('\n');

const destination = resolve(root, 'bundle.css');
if (process.argv.includes('--check')) {
  if (readFileSync(destination, 'utf8') !== result) {
    console.error('CSS_BUNDLE_STALE: regenerate with node scripts/build-css-bundle.mjs');
    process.exit(1);
  }
  console.log('CSS_BUNDLE_PASS: ' + sources.length + ' ordered sources');
} else {
  writeFileSync(destination, result, 'utf8');
  console.log('Generated bundle.css from ' + sources.length + ' ordered sources');
}
